# jax.example_libraries.stax (R/example_stax.R). Expected values were produced by jax
# 0.12.0.1 on CPU with the keys below; arrays are listed in C order as
# list(shape, values, dtype).

stx_t_c_ravel <- function(x) {
  d <- dim(x)
  if (length(d) <= 1L) return(as.vector(x))
  as.vector(aperm(x, length(d):1))
}

# Exact comparison (tol = 0) unless a relative tolerance is given.
stx_t_expect <- function(x, ref, tol = 0) {
  expect_identical(jaxR::dtype(x), ref[[3L]])
  expect_identical(as.integer(dim(x)), as.integer(ref[[1L]]))
  got <- stx_t_c_ravel(as.array(x))
  if (tol == 0) expect_identical(as.numeric(got), as.numeric(ref[[2L]]))
  else expect_equal(as.numeric(got), as.numeric(ref[[2L]]), tolerance = tol)
}

stx_t_x <- function() jnp_reshape(jnp_arange(12, dtype = "float32"), c(4, 3)) / 6 - 1

stx_t_skip_missing <- function(...) {
  for (f in c(...)) {
    skip_if_not(exists(f, envir = asNamespace("jaxR"), inherits = FALSE), paste(f, "is not available"))
  }
}

