test_that("Dense and serial match stax", {
  skip_if_no_backend()
  key <- random_key(0)
  x <- stx_t_x()
  d <- stax_Dense(2L)
  res <- d$init_fun(key, c(-1L, 3L))
  expect_identical(res$output_shape, c(-1L, 2L))
  stx_t_expect(res$params[[1L]], stax_ref$dense_W)
  stx_t_expect(res$params[[2L]], stax_ref$dense_b)
  stx_t_expect(d$apply_fun(res$params, x), stax_ref$dense_out)
  mlp <- stax_serial(stax_Dense(5L), stax_Relu, stax_Dense(4L), stax_Tanh, stax_Dense(2L),
                     stax_LogSoftmax)
  res <- mlp$init_fun(key, c(-1L, 3L))
  expect_identical(res$output_shape, c(-1L, 2L))
  expect_length(res$params, 6L)
  expect_identical(res$params[[2L]], list())
  stx_t_expect(res$params[[1L]][[1L]], stax_ref$mlp_W0)
  stx_t_expect(res$params[[3L]][[1L]], stax_ref$mlp_W2)
  stx_t_expect(res$params[[5L]][[2L]], stax_ref$mlp_b4)
  stx_t_expect(mlp$apply_fun(res$params, x), stax_ref$mlp_out, tol = 1e-6)
  stx_t_expect(jit(mlp$apply_fun)(res$params, x), stax_ref$mlp_out, tol = 1e-6)
  # per example application under vmap
  got <- vmap(function(r) mlp$apply_fun(res$params, r))(x)
  stx_t_expect(got, stax_ref$mlp_out, tol = 1e-6)
})

test_that("BatchNorm, elementwise layers and shape_dependent match stax", {
  skip_if_no_backend()
  key <- random_key(0)
  x <- stx_t_x()
  x4 <- random_normal(random_key(1), c(2, 3, 3, 2))
  bn <- stax_BatchNorm()
  res <- bn$init_fun(key, c(2L, 3L, 3L, 2L))
  expect_identical(dim(res$params[[1L]]), 2L)
  p <- list(res$params[[1L]] + 0.5, res$params[[2L]] * 2)
  stx_t_expect(bn$apply_fun(p, x4), stax_ref$bn_out, tol = 1e-6)
  bn2 <- stax_BatchNorm(axis = c(0L, 2L), center = FALSE)
  res2 <- bn2$init_fun(key, c(2L, 3L, 3L, 2L))
  expect_identical(res2$params[[1L]], list())
  stx_t_expect(res2$params[[2L]], stax_ref$bn2_gamma)
  stx_t_expect(bn2$apply_fun(res2$params, x4), stax_ref$bn2_out, tol = 1e-6)
  for (nm in c("Gelu", "Softmax", "Elu", "Selu", "LeakyRelu", "Softplus", "Sigmoid", "Exp")) {
    layer <- get(paste0("stax_", nm))
    expect_identical(layer$init_fun(key, c(4L, 3L))$output_shape, c(4L, 3L))
    stx_t_expect(layer$apply_fun(list(), x), stax_ref[[paste0("elt_", nm)]], tol = 1e-6)
  }
  sd <- stax_shape_dependent(function(s) stax_Dense(s[length(s)] * 2L))
  res <- sd$init_fun(key, c(-1L, 3L))
  expect_identical(res$output_shape, c(-1L, 6L))
  stx_t_expect(sd$apply_fun(res$params, x), stax_ref$sd_out, tol = 1e-6)
  fl <- stax_Flatten
  expect_identical(fl$init_fun(key, c(-1L, 2L, 3L))$output_shape, c(-1L, 6L))
  expect_identical(dim(fl$apply_fun(list(), x4)), c(2L, 18L))
  expect_identical(as.array(stax_Identity$apply_fun(list(), x)), as.array(x))
})

test_that("fan out, parallel and fan in layers match stax", {
  skip_if_no_backend()
  x <- stx_t_x()
  net <- stax_serial(stax_FanOut(2L), stax_parallel(stax_Dense(3L), stax_Identity), stax_FanInSum)
  res <- net$init_fun(random_key(3), c(-1L, 3L))
  expect_identical(res$output_shape, c(-1L, 3L))
  stx_t_expect(net$apply_fun(res$params, x), stax_ref$res_out, tol = 1e-6)
  cat_net <- stax_serial(stax_FanOut(2L), stax_parallel(stax_Dense(2L), stax_Dense(4L)),
                         stax_FanInConcat())
  res <- cat_net$init_fun(random_key(4), c(-1L, 3L))
  expect_identical(as.integer(res$output_shape), c(-1L, 6L))
  stx_t_expect(cat_net$apply_fun(res$params, x), stax_ref$cat_out, tol = 1e-6)
  fo <- stax_FanOut(3L)$init_fun(random_key(0), c(2L, 3L))
  expect_identical(fo$output_shape, rep(list(c(2L, 3L)), 3L))
})

test_that("Dropout matches stax and requires a key", {
  skip_if_no_backend()
  x <- stx_t_x()
  d <- stax_Dropout(0.5)
  stx_t_expect(d$apply_fun(list(), jnp_ones(c(2, 4)), rng = random_key(5)), stax_ref$dropout)
  expect_error(d$apply_fun(list(), x), "requires apply_fun to be called with a PRNG key")
  # outside training the inputs pass through, but a key is still required (as in JAX)
  expect_identical(as.array(stax_Dropout(0.5, mode = "test")$apply_fun(list(), x, rng = random_key(5))),
                   as.array(x))
  s <- stax_serial(stax_Dense(4L), stax_Dropout(0.7), stax_Dense(1L))
  res <- s$init_fun(random_key(0), c(-1L, 3L))
  stx_t_expect(s$apply_fun(res$params, x, rng = random_key(6)), stax_ref$serial_dropout, tol = 1e-6)
})

test_that("convolution and pooling layers match stax", {
  skip_if_no_backend()
  stx_t_skip_missing("lax_conv_general_dilated", "lax_conv_transpose", "lax_reduce_window")
  key <- random_key(0)
  img <- random_normal(random_key(2), c(2, 5, 5, 3))
  conv <- stax_Conv(4L, c(3L, 3L), strides = c(1L, 2L), padding = "SAME")
  res <- conv$init_fun(key, c(2L, 5L, 5L, 3L))
  expect_identical(as.integer(res$output_shape), c(2L, 5L, 3L, 4L))
  stx_t_expect(res$params[[1L]], stax_ref$conv_W)
  stx_t_expect(conv$apply_fun(res$params, img), stax_ref$conv_out, tol = 1e-5)
  imgc <- jnp_transpose(img, c(0L, 3L, 1L, 2L))
  gc <- stax_GeneralConv(c("NCHW", "OIHW", "NCHW"), 2L, c(2L, 2L))
  res <- gc$init_fun(key, c(2L, 3L, 5L, 5L))
  expect_identical(as.integer(res$output_shape), c(2L, 2L, 4L, 4L))
  stx_t_expect(gc$apply_fun(res$params, imgc), stax_ref$gconv_out, tol = 1e-5)
  ct <- stax_ConvTranspose(2L, c(3L, 3L), strides = c(2L, 2L))
  res <- ct$init_fun(key, c(2L, 5L, 5L, 3L))
  expect_identical(as.integer(res$output_shape), c(2L, 11L, 11L, 2L))
  stx_t_expect(ct$apply_fun(res$params, img), stax_ref$convt_out, tol = 1e-5)
  x1d <- lax_index_in_dim(img, 0L, axis = 2L, keepdims = FALSE)
  c1 <- stax_Conv1DTranspose(2L, 3L, padding = "SAME")
  res <- c1$init_fun(key, c(2L, 5L, 3L))
  expect_identical(as.integer(res$output_shape), c(2L, 5L, 2L))
  stx_t_expect(c1$apply_fun(res$params, x1d), stax_ref$convt1_out, tol = 1e-5)
  mp <- stax_MaxPool(c(2L, 2L))
  expect_identical(as.integer(mp$init_fun(key, c(-1L, 8L, 8L, 3L))$output_shape), c(0L, 7L, 7L, 3L))
  stx_t_expect(mp$apply_fun(list(), img), stax_ref$maxpool)
  stx_t_expect(stax_SumPool(c(2L, 2L), strides = c(2L, 2L), padding = "SAME")$apply_fun(list(), img),
               stax_ref$sumpool, tol = 1e-6)
  ap <- stax_AvgPool(c(3L, 2L), strides = c(2L, 1L), padding = "SAME")
  expect_identical(as.integer(ap$init_fun(key, c(2L, 5L, 5L, 3L))$output_shape), c(2L, 3L, 5L, 3L))
  stx_t_expect(ap$apply_fun(list(), img), stax_ref$avgpool, tol = 1e-6)
  stx_t_expect(stax_AvgPool(c(2L, 2L), spec = "NCHW")$apply_fun(list(), imgc), stax_ref$avgpool_spec,
               tol = 1e-6)
})

test_that("a stax MLP trained with adam follows the loss trajectory of JAX", {
  skip_if_no_backend()
  X <- random_normal(random_key(11), c(16, 3))
  Y <- jnp_sin(jnp_sum(X, axis = 1L, keepdims = TRUE))
  net <- stax_serial(stax_Dense(8L), stax_Relu, stax_Dense(4L), stax_Tanh, stax_Dense(1L))
  p0 <- net$init_fun(random_key(10), c(-1L, 3L))$params
  loss <- function(p) jnp_mean((net$apply_fun(p, X) - Y)^2L)
  vg <- jit(value_and_grad(loss))
  opt <- optimizers_adam(0.05)
  st <- opt$init_fn(p0)
  losses <- numeric(0)
  for (i in 0:24) {
    r <- vg(opt$params_fn(st))
    losses <- c(losses, as.numeric(as.array(r[[1L]])))
    st <- opt$update_fn(i, r[[2L]], st)
  }
  expect_equal(losses, stax_ref$train_losses[[2L]], tolerance = 1e-5)
  expect_lt(losses[25L], losses[1L] / 2)
  stx_t_expect(opt$params_fn(st)[[1L]][[1L]], stax_ref$train_final_W0, tol = 1e-4)
})
